using System;using System.Linq;using System.IO;using Verse;using Verse.AI;using RimWorld;using PlayableRecreation;using PlayableRecreation.UI;using PRQA;
public static class Command{public static string Run(){Host.Watch=null;foreach(var w in Find.WindowStack.Windows.ToList())if(w is Dialog_MiniGame||w is FloatMenu||w is Dialog_Difficulty||w.GetType().Name.Contains("Faction"))w.Close(false);TogetherMatch.Reset();TogetherInvite.Reset();var map=Find.CurrentMap;var pair=(Pawn[])Host.State["pair"];foreach(var p in map.mapPawns.FreeColonistsSpawned.ToList()){p.jobs.EndCurrentJob(JobCondition.InterruptForced);p.drafter.Drafted=!pair.Take(2).Contains(p);}var b=ThingMaker.MakeThing(DefDatabase<ThingDef>.GetNamed("ChessTable"),ThingDefOf.WoodLog);b.SetFaction(Faction.OfPlayer);GenSpawn.Spawn(b,new IntVec3(130,0,80),map);foreach(var cell in GenAdjFast.AdjacentCellsCardinal(b)){if(!cell.Standable(map))continue;var chair=ThingMaker.MakeThing(ThingDefOf.DiningChair,ThingDefOf.WoodLog);chair.SetFaction(Faction.OfPlayer);GenSpawn.Spawn(chair,cell,map);}Host.State["chess"]=b;for(int i=0;i<2;i++){pair[i].Position=b.Position+new IntVec3(-5+i,0,-4);pair[i].Notify_Teleported();pair[i].needs.food.CurLevelPercentage=1;pair[i].needs.rest.CurLevelPercentage=1;}PRMod.Settings.playTogether=true;PRMod.Settings.immersionMode=true;PRMod.Settings.playTogetherInvites=false;GameEntry.Commit(b.TryGetComp<CompMiniGame>().Game,b,pair[0],pair[1],2,false);int start=Find.TickManager.TicksGame,last=-1;var log=Host.Root+"/fresh-arrival.txt";File.WriteAllText(log,"Fresh isolated chessboard with chairs; other colonists drafted to avoid incidental recreation reservations.\n");Host.Watch=()=>{int e=Find.TickManager.TicksGame-start;bool open=Find.WindowStack.Windows.Any(w=>w is Dialog_MiniGame);if(e/50!=last){last=e/50;File.AppendAllText(log,e+" window="+open+" "+string.Join(" | ",pair.Take(2).Select(p=>p+" job="+p.CurJob+" pos="+p.Position))+"\n"+TogetherMatch.Describe()+"\n");}if(open||e>2800){Find.TickManager.CurTimeSpeed=TimeSpeed.Paused;Host.Watch=null;}};Find.TickManager.CurTimeSpeed=TimeSpeed.Normal;return "Fresh isolated chess pair requested.";}}


